-- Sexta tanda de la base (1.25): recetas, parte 4 de 8. Después de seed-8-alimentos.sql. Se puede correr de nuevo: agrega solo lo que falta. Generado con scripts/gen-seed.mjs

insert into public.recipes (slug, name, minutes, servings, meal_types, portable, steps) values
  ('crema-de-calabaza-con-semillas-de-zapallo', 'Crema de calabaza con semillas de zapallo', 35, 4, '{almuerzo,cena}', true, 'Pelás la calabaza y la papa y las cortás en cubos.
Sofreís la cebolla picada con el aceite 4 minutos. Sumás las verduras y el caldo (cubre justo) con sal y pimienta; tapás y hervís 20 minutos hasta que estén bien tiernas.
Procesás con minipimer hasta que quede lisa. Si queda muy espesa, la aligerás con agua caliente; si queda líquida, la hervís 5 minutos sin tapa.
Servís con semillas de zapallo tostadas y un hilo de aceite de oliva.
Rinde 4 platos. Se conserva 4 días en la heladera y se puede freezar.'),
  ('crema-de-champinones-con-pollo-desmenuzado', 'Crema de champiñones con pollo desmenuzado', 35, 4, '{almuerzo,cena}', true, 'Laminás los champiñones y cortás la papa en cubos.
Sofreís la cebolla picada con el aceite 4 minutos. Sumás las verduras y el caldo (cubre justo) con sal y pimienta; tapás y hervís 20 minutos hasta que estén bien tiernas.
Procesás con minipimer hasta que quede lisa. Si queda muy espesa, la aligerás con agua caliente; si queda líquida, la hervís 5 minutos sin tapa.
Servís con pollo desmenuzado (de una pata o una pechuga hervida) calentado en la sopa.
Rinde 4 platos. Se conserva 4 días en la heladera y se puede freezar.'),
  ('crema-de-zapallo-y-jengibre-con-semillas-de-zapallo', 'Crema de zapallo y jengibre con semillas de zapallo', 35, 4, '{almuerzo,cena}', true, 'Pelás el zapallo y la papa y los cortás en cubos; rallás el jengibre.
